const SIGNAL_BANDS: ReadonlyArray<readonly [limit: number, label: string]> = [
  [50, "standby"],
  [200, "idle"],
  [600, "active"],
  [900, "loaded"],
  [Infinity, "critical"],
];

// Severity ordering, shared by per-channel "worst" and report "worst".
const SEVERITY: Record<string, number> = {
  standby: 0,
  idle: 1,
  active: 2,
  loaded: 3,
  critical: 4,
  negative: 5,
};

// Classifications worth surfacing as alerts.
const ALERTING_LABELS = new Set(["negative", "loaded", "critical"]);

export function processBatch(raw: unknown): BatchResult {
  const error = validateBatch(raw);
  if (error !== null) {
    return { ok: false, error };
  }
  const entries = (raw as { readings: unknown[] }).readings;
  const parsed: ParsedReading[] = [];
  for (let index = 0; index < entries.length; index++) {
    const reading = parseReading(entries[index], index);
    if (typeof reading === "string") {
      return { ok: false, error: reading };
    }
    const toMillivolts = UNIT_TO_MILLIVOLTS[reading.unit] ?? ((value: number) => value);
    parsed.push({ channel: reading.channel, millivolts: toMillivolts(reading.value), at: reading.at });
  }

  const labels = parsed.map((reading) => classifySignal(reading.millivolts));

  const alerts: string[] = [];
  const channels: Record<string, ChannelSummary> = {};
  let worst = "standby";
  for (let index = 0; index < parsed.length; index++) {
    const { channel, millivolts } = parsed[index];
    const label = labels[index];
    if (ALERTING_LABELS.has(label)) {
      alerts.push(channel + ":" + label);
    }
    const existing = channels[channel];
    if (existing === undefined) {
      channels[channel] = { count: 1, min: millivolts, max: millivolts, worst: label };
    } else {
      existing.count += 1;
      existing.min = Math.min(existing.min, millivolts);
      existing.max = Math.max(existing.max, millivolts);
      if (SEVERITY[label] > SEVERITY[existing.worst]) {
        existing.worst = label;
      }
    }
    if (SEVERITY[label] > SEVERITY[worst]) {
      worst = label;
    }
  }

  return {
    ok: true,
    readings: parsed.length,
    labels,
    channels,
    alerts,
    report: buildReport(parsed.length, Object.keys(channels).length, alerts.length, worst),
  };
}

function validateBatch(raw: unknown): string | null {
  if (typeof raw !== "object" || raw === null) {
    return "malformed batch";
  }
  const batch = raw as Record<string, unknown>;
  if (!Array.isArray(batch.readings)) {
    return "missing readings";
  }
  if (batch.readings.length === 0) {
    return "empty batch";
  }
  if (batch.readings.length > MAX_READINGS) {
    return "batch too large";
  }
  return null;
}

function parseReading(entry: unknown, index: number): Reading | string {
  if (typeof entry !== "object" || entry === null) {
    return "reading " + index + ": malformed";
  }
  const record = entry as Record<string, unknown>;
  if (typeof record.channel !== "string" || record.channel.length === 0) {
    return "reading " + index + ": bad channel";
  }
  if (UNITS.indexOf(record.unit as string) < 0) {
    return "reading " + index + ": bad unit";
  }
  if (!Number.isInteger(record.value)) {
    return "reading " + index + ": bad value";
  }
  if (!Number.isInteger(record.at) || (record.at as number) < 0) {
    return "reading " + index + ": bad timestamp";
  }
  return { channel: record.channel, unit: record.unit as string, value: record.value as number, at: record.at as number };
}

export function classifySignal(millivolts: number): string {
  if (millivolts < 0) {
    return "negative";
  }
  for (const [limit, label] of SIGNAL_BANDS) {
    if (millivolts < limit) {
      return label;
    }
  }
  return "critical";
}

function buildReport(readingCount: number, channelCount: number, alertCount: number, worst: string): string {
  return "readings=" + readingCount + ";channels=" + channelCount + ";alerts=" + alertCount + ";worst=" + worst;
}

