npx --yes tsx -e "
const {processBatch, classifySignal, Reading} = await import('/tmp/eval-work-bxKpBi/process_batch.ts');
const readings = [
  {channel:'a', unit:'uV', value:0, at:1},
  {channel:'a', unit:'uV', value:120000, at:2},
  {channel:'b', unit:'V', value:1.5, at:3},
  {channel:'c', unit:'mV', value:950, at:4},
  {channel:'d', unit:'mV', value:-5, at:5},
];
const r = processBatch({readings});
console.log(JSON.stringify(r, null, 2));
console.log('classify:', [0,49,50,199,200,599,600,899,900,950,-1].map(x=>classifySignal(x)).join(','));
console.log('err1', processBatch({readings:[]}));
console.log('err2', processBatch(null));
console.log('err3', processBatch({readings:new Array(501).fill({})}));
" 2>&1 | head -60

